function resolveRead(responses, replicas) {
  const newest = responses.reduce((best, r) =>
    r.version > best.version ? r : best
  );
  responses.forEach((r, i) => {
    if (r.version < newest.version) {
      replicas[i].write(newest.version, newest.value); // read repair
    }
  });
  return newest.value;
}
